def format_comparison(mc: ExactResult, ex: ExactResult, draws: int) -> str:
    """Side-by-side MC-vs-exact table with z-scores."""
    mcv, exv = _metric_values(mc), _metric_values(ex)
    sigs = mc_sigmas(ex, draws)
    lines = [
        f"{'metric':<14} {'Monte Carlo':>14} {'exact':>14} {'rel err':>9} {'z':>7}",
        "-" * 62,
    ]
    for name in mcv:
        got, want = mcv[name], exv[name]
        rel = (got - want) / want if want else float("nan")
        z = (got - want) / sigs[name] if sigs[name] else float("nan")
        lines.append(f"{name:<14} {got:>14,.4f} {want:>14,.4f} {rel:>8.2%} {z:>6.2f}")
    return "\n".join(lines)


